<template><main class="admin-content"><NuxtLink to="/admin/accounting" class="text-sm font-bold text-blue-600">← Accounting</NuxtLink><h1 class="mt-2 text-3xl font-black">General Journal</h1><div v-if="msg" class="my-4 rounded-lg bg-slate-100 p-3">{{msg}}</div><section class="admin-panel mt-5 p-5"><div class="grid gap-3 md:grid-cols-3"><label><span class="label">Date</span><input v-model="f.journal_date" type="date" class="input"></label><label><span class="label">Reference</span><input v-model="f.reference" class="input"></label><label><span class="label">Description</span><input v-model="f.description" class="input"></label></div><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[700px] text-sm"><thead><tr class="bg-slate-50 text-left"><th class="p-2">Account</th><th>Description</th><th class="text-right">Debit</th><th class="text-right">Credit</th><th></th></tr></thead><tbody><tr v-for="(l,n) in f.lines" :key="n"><td class="p-2"><select v-model.number="l.account_id" class="input"><option :value="0">Choose account…</option><option v-for="a in accounts" :value="a.id">{{a.code}} — {{a.name}}</option></select></td><td><input v-model="l.description" class="input"></td><td><input v-model.number="l.debit" type="number" min="0" step=".01" class="input text-right"></td><td><input v-model.number="l.credit" type="number" min="0" step=".01" class="input text-right"></td><td><button class="text-red-600" @click="f.lines.splice(n,1)">Remove</button></td></tr></tbody></table></div><div class="mt-3 flex flex-wrap items-center justify-between gap-3"><button class="btn-secondary" @click="f.lines.push(line())">+ Line</button><div class="flex gap-6 font-bold"><span>Debits {{money(debits)}}</span><span>Credits {{money(credits)}}</span><span :class="balanced?'text-emerald-700':'text-red-600'">{{balanced?'Balanced':'Out of balance'}}</span></div><button class="btn-primary" :disabled="!balanced||!f.description" @click="post">Post Journal</button></div></section><section class="admin-panel mt-5 p-5"><h2 class="text-xl font-black">Recent Journals</h2><div v-for="j in journals" :key="j.id" class="mt-3 rounded-lg border p-3"><div class="flex justify-between gap-3"><div><b>J{{String(j.journal_number).padStart(5,'0')}} — {{j.description}}</b><div class="text-xs text-slate-500">{{j.journal_date}} · {{j.reference||'No reference'}}</div></div><span class="text-xs font-bold uppercase">{{j.status}}</span></div></div></section></main></template><script setup lang="ts">definePageMeta({layout:"admin",middleware:["admin"]});const{adminFetch}=useAdminFetch(),accounts=ref<any[]>([]),journals=ref<any[]>([]),msg=ref("");const line=()=>({account_id:0,description:"",debit:0,credit:0});const f=reactive<any>({journal_date:new Date().toISOString().slice(0,10),reference:"",description:"",lines:[line(),line()]});const money=(v:any)=>new Intl.NumberFormat("en-AU",{style:"currency",currency:"AUD"}).format(Number(v||0));const debits=computed(()=>f.lines.reduce((s:number,l:any)=>s+Number(l.debit||0),0)),credits=computed(()=>f.lines.reduce((s:number,l:any)=>s+Number(l.credit||0),0)),balanced=computed(()=>debits.value>0&&Math.round(debits.value*100)===Math.round(credits.value*100));async function load(){[accounts.value,journals.value]=await Promise.all([adminFetch("/api/admin/accounting/accounts"),adminFetch("/api/admin/accounting/journals")])}async function post(){try{await adminFetch("/api/admin/accounting/journals",{method:"POST",body:f});msg.value="Journal posted.";Object.assign(f,{journal_date:new Date().toISOString().slice(0,10),reference:"",description:"",lines:[line(),line()]});await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}onMounted(load)</script><style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.input{@apply w-full rounded-lg border border-slate-300 px-3 py-2}.label{@apply mb-1 block text-sm font-bold}.btn-primary{@apply rounded-lg bg-blue-600 px-5 py-2.5 font-bold text-white disabled:opacity-40}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 font-bold}</style>